    /// `len` bytes of the keystream by `f`, into a buffer apart from the
    /// zeros it XORs (or in place), with the working area `off` bytes past
    /// its alignment.
    fn keystream(f: Cand, len: usize, off: usize, in_place: bool) -> Vec<u8> {
        let mut w = work();
        let src = vec![0u8; len];
        let mut dst = vec![0u8; len];
        let p = w.0.as_mut_ptr();
        // SAFETY: the state's 64 bytes, `len` bytes of data and 320 bytes of
        // working area are valid; the functions follow cdecl.
        unsafe {
            if in_place {
                f(p, dst.as_ptr(), len as u32, p.add(128 + off), dst.as_mut_ptr());
            } else {
                f(p, src.as_ptr(), len as u32, p.add(128 + off), dst.as_mut_ptr());
            }
        }
        dst
    }

    pub fn candidates(round: u32) {
        let ssse3 = std::is_x86_feature_detected!("ssse3");
        let line = |mode: &str, name: &str, bytes: usize, calls: u32, (before, after, min, med): (u32, u32, u32, u32)| {
            eprintln!(
                "xchacha {round} {mode:<7} {name:<12} {bytes:>5} xinuse {before:#x}->{after:#x} min {:>8.1} median {:>8.1} ns, {:>6} ps/block",
                f64::from(min) / f64::from(calls),
                f64::from(med) / f64::from(calls),
                u64::from(med) * 1000 / (u64::from(calls) * (bytes as u64 / 64))
            );
        };
        // Every candidate gives the library's keystream: at lengths that end
        // in a turn, within one, and in the block function's 64 bytes or fewer.
        let want = |len: usize| {
            let mut v = vec![0u8; len];
            ChaCha20::new(&KEY, &NONCE).apply_keystream(&mut v);
            v
        };
        for (m, mode) in MODES.iter().enumerate() {
            for (name, f, needs) in CANDS {
                if needs && !ssse3 {
                    continue;
                }
                if [BYTES, 1024, 1000, 1064, 300, 65, 64, 1, 0]
                    .iter()
                    .any(|&n| keystream(f, n, 0, true) != want(n) || keystream(f, n, 12, false) != want(n))
                {
                    eprintln!("xchacha {round} {mode} {name} WRONG: not the library's keystream");
                    continue;
                }
                for off in [0usize, 12] {
                    let mut w = work();
                    let mut b = Buf([0; BYTES]);
                    let (p, d) = (w.0.as_mut_ptr(), b.0.as_mut_ptr());
                    // SAFETY: as in `keystream`.
                    let t = time(m, || unsafe {
                        f(black_box(p), d, BYTES as u32, p.add(128 + off), black_box(d))
                    });
                    if let Some(t) = t {
                        let label = if off == 0 { name.to_string() } else { format!("{name}@{off}") };
                        line(mode, &label, BYTES, 1, t);
                    }
                }
            }
            // The library, with the key's setup: ChaCha20, and
            // ChaCha20-Poly1305's seal with 16 bytes of additional data.
            let mut b = Buf([0x5a; BYTES]);
            for (bytes, calls) in [(BYTES, 1u32), (1024, 16)] {
                let t = time(m, || {
                    for _ in 0..calls {
                        ChaCha20::new(black_box(&KEY), &NONCE).apply_keystream(black_box(&mut b.0[..bytes]));
                    }
                });
                if let Some(t) = t {
                    line(mode, "lib-chacha20", bytes, calls, t);
                }
                let t = time(m, || {
                    for _ in 0..calls {
                        black_box(
                            ChaCha20Poly1305::new(black_box(&KEY))
                                .encrypt_in_place(&[0x24; 12], &[0x5a; 16], black_box(&mut b.0[..bytes]))
                                .unwrap(),
                        );
                    }
                });
                if let Some(t) = t {
                    line(mode, "lib-cp-seal", bytes, calls, t);
                }
            }
        }
        vzeroupper();
    }
