    /// Every candidate, in each state of `MODES`.
    pub fn candidates(round: u32) {
        if !(std::is_x86_feature_detected!("aes") && std::is_x86_feature_detected!("ssse3")) {
            eprintln!("xsm4w {round} skipped: no AES-NI or no SSSE3");
            return;
        }
        let mut d = Box::new(Buf([0; BYTES]));
        let mut x = 0x9e37_79b9_7f4a_7c15u64;
        for v in d.0.iter_mut() {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            *v = (x >> 24) as u8;
        }
        let key: [u8; 16] = std::array::from_fn(|i| (17 * i + 3) as u8);
        let ctr0: [u8; 16] = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5, 8, 0, 0, 1, 0xf0];
        let mut out = vec![0u8; BYTES + 16];
        let ecb = Cipher::sm4_ecb();
        let octr = Cipher::sm4_ctr();
        let mut wrong: Vec<&str> = Vec::new();
        let mut sched = [0u8; 128];
        kx(&key, &mut sched);
        if sched != SCHED.0 {
            eprintln!("xsm4w {round} kx WRONG: not the schedule of the key");
            wrong.push("kx");
        }
        for blocks in [1usize, 2, 3, 4, 5, 6, 7, 8, 9, 68, 70] {
            let mut want = d.clone();
            Sm4Ecb::new(&key).encrypt(&mut want.0[..16 * blocks]).unwrap();
            for (name, f) in ECB {
                if name == "wfd" && blocks % 4 != 0 {
                    continue;
                }
                let mut b = d.clone();
                let mut v = ctr0;
                run(f, &SCHED.0, &mut v, &mut b.0, blocks);
                if b.0 != want.0 && !wrong.contains(&name) {
                    eprintln!("xsm4w {round} {name} WRONG: not the library's ECB encryption on {blocks} blocks");
                    wrong.push(name);
                }
            }
            let mut want = d.clone();
            Sm4Ctr::new(&key, &ctr0).apply_keystream(&mut want.0[..16 * blocks]).unwrap();
            for (name, f) in CTR {
                let mut b = d.clone();
                let mut v = ctr0;
                run(f, &SCHED.0, &mut v, &mut b.0, blocks);
                if b.0 != want.0 && !wrong.contains(&name) {
                    eprintln!("xsm4w {round} {name} WRONG: not the library's CTR on {blocks} blocks");
                    wrong.push(name);
                }
            }
        }
        let mut b = d.clone();
        for (m, state) in MODES.iter().enumerate() {
            let line = |name: &str, bytes: usize, reps: usize, t: Option<(u32, u32, u64, u64)>| {
                if let Some((before, after, min, med)) = t {
                    eprintln!(
                        "xsm4w {round} {state:<7} {name:<11} {bytes:>5} c128 xinuse {before:#x}->{after:#x} n 41 min {:>10.1} median {:>10.1} ns",
                        min as f64 / reps as f64,
                        med as f64 / reps as f64
                    );
                }
            };
            if !wrong.contains(&"kx") {
                let mut s = [0u8; 128];
                line("kx", 0, 64, time(m, || {
                    for _ in 0..64 {
                        kx(black_box(&key), &mut s);
                        black_box(&s);
                    }
                }));
            }
            line("libkey", 0, 64, time(m, || {
                for _ in 0..64 {
                    let c = Sm4Ecb::new(black_box(&key));
                    black_box(&c);
                }
            }));
            line("osslkey", 0, 64, time(m, || {
                for _ in 0..64 {
                    let mut o = Crypter::new(ecb, Mode::Encrypt, black_box(&key), None).unwrap();
                    o.pad(false);
                    black_box(&o);
                }
            }));
            for bytes in [16usize, 64, 256, 1024, BYTES] {
                let reps = (4096 / bytes).max(1);
                let n = bytes / 16;
                for (name, f) in ECB.into_iter().chain(CTR) {
                    if wrong.contains(&name) || (name == "wfd" && n % 4 != 0) {
                        continue;
                    }
                    let mut v = ctr0;
                    line(name, bytes, reps, time(m, || {
                        for _ in 0..reps {
                            run(f, black_box(&SCHED.0), &mut v, black_box(&mut b.0), n);
                        }
                    }));
                    line(&format!("{name}+key"), bytes, reps, time(m, || {
                        for _ in 0..reps {
                            let c = Sm4Ecb::new(black_box(&key));
                            black_box(&c);
                            run(f, black_box(&SCHED.0), &mut v, black_box(&mut b.0), n);
                        }
                    }));
                    if AFTER_KX.contains(&name) && !wrong.contains(&"kx") {
                        line(&format!("{name}+kx"), bytes, reps, time(m, || {
                            for _ in 0..reps {
                                let mut s = [0u8; 128];
                                kx(black_box(&key), &mut s);
                                run(f, &s, &mut v, black_box(&mut b.0), n);
                            }
                        }));
                    }
                }
                let c = Sm4Ecb::new(&key);
                line("lib", bytes, reps, time(m, || {
                    for _ in 0..reps {
                        c.encrypt(black_box(&mut b.0[..bytes])).unwrap();
                    }
                }));
                line("lib+key", bytes, reps, time(m, || {
                    for _ in 0..reps {
                        Sm4Ecb::new(black_box(&key)).encrypt(black_box(&mut b.0[..bytes])).unwrap();
                    }
                }));
                let mut c = Sm4Ctr::new(&key, &ctr0);
                line("libctr", bytes, reps, time(m, || {
                    for _ in 0..reps {
                        c.apply_keystream(black_box(&mut b.0[..bytes])).unwrap();
                    }
                }));
                line("libctr+key", bytes, reps, time(m, || {
                    for _ in 0..reps {
                        Sm4Ctr::new(black_box(&key), &ctr0).apply_keystream(black_box(&mut b.0[..bytes])).unwrap();
                    }
                }));
                for (name, cipher, iv) in [("ossl", ecb, None), ("osslctr", octr, Some(&ctr0[..]))] {
                    let mut o = Crypter::new(cipher, Mode::Encrypt, &key, iv).unwrap();
                    o.pad(false);
                    line(name, bytes, reps, time(m, || {
                        for _ in 0..reps {
                            o.update(black_box(&b.0[..bytes]), black_box(&mut out)).unwrap();
                        }
                    }));
                    line(&format!("{name}+key"), bytes, reps, time(m, || {
                        for _ in 0..reps {
                            let mut o = Crypter::new(cipher, Mode::Encrypt, black_box(&key), iv).unwrap();
                            o.pad(false);
                            o.update(black_box(&b.0[..bytes]), black_box(&mut out)).unwrap();
                        }
                    }));
                }
            }
        }
        done();
    }
