/// // kind 0: ML-DSA (Algorithm 41, layers 128 .. 1; zt[i] = zeta_i R mod q); kind 1: ML-KEM (Algorithm 9, layers
/// // 128 .. 2; zt[i] = zeta_i R mod q). lazy: no reduction but Montgomery's until the end.
/// INL void ntt4(uint32_t *w, const uint32_t *zt, const uint32_t *K, const int kind, const int lazy) {
///   const C4 k = consts(K);
///   const V fv = S1(K[4]), m23 = S1(K[7]);
///   const V c = lazy && kind == 0 ? ADD(k.q, k.q) : k.q;
///   const V o = OFF(c, &k), o0 = OFF(_mm_setzero_si128(), &k);
///   unsigned m = 0;
///   for (unsigned len = 128; len >= 4; len >>= 1)
///     for (unsigned start = 0; start < 256; start += 2 * len) {
///       V z = S1(zt[++m]);
///       for (unsigned j = start; j < start + len; j += 4) {
///         V a = LD(w + j), b = LD(w + j + len), t = mont(b, z, &k);
///         if (!lazy) t = csub(t, &k);
///         V a1 = ADD(a, t), b1 = subo(a, t, o, &k);
///         if (!lazy) { a1 = csub(a1, &k); b1 = csub(b1, &k); }
///         ST(w + j, a1); ST(w + j + len, b1);
///       }
///     }
///   for (unsigned j = 0; j < 256; j += 8) {
///     V x = LD(w + j), y = LD(w + j + 4), a = _mm_unpacklo_epi64(x, y), b = _mm_unpackhi_epi64(x, y);
///     V z = _mm_shuffle_epi32(_mm_loadl_epi64((const V *)(zt + m + 1)), 0x98); m += 2;
///     V t = mont(b, z, &k);
///     if (!lazy) t = csub(t, &k);
///     V a1 = ADD(a, t), b1 = subo(a, t, o, &k);
///     if (!lazy) { a1 = csub(a1, &k); b1 = csub(b1, &k); }
///     else if (kind == 1) { a1 = fin(a1, 1, &k, fv, m23, o0); b1 = fin(b1, 1, &k, fv, m23, o0); }
///     ST(w + j, _mm_unpacklo_epi64(a1, b1)); ST(w + j + 4, _mm_unpackhi_epi64(a1, b1));
///   }
///   if (kind == 0)
///     for (unsigned j = 0; j < 256; j += 4) {
///       V x = LD(w + j), z = _mm_shuffle_epi32(_mm_loadl_epi64((const V *)(zt + m + 1)), 0x98); m += 2;
///       V t = mont1(_mm_srli_epi64(x, 32), z, &k);
///       if (!lazy) t = csub(t, &k);
///       V a1 = ADD(x, t), b1 = subo(x, t, o, &k);
///       if (!lazy) { a1 = csub(a1, &k); b1 = csub(b1, &k); }
///       x = _mm_or_si128(_mm_and_si128(a1, k.lo), _mm_slli_epi64(b1, 32));
///       if (lazy) x = fin(x, 0, &k, fv, m23, o0);
///       ST(w + j, x);
///     }
/// }
/// // The inverse (Algorithms 42 and 10): zt[i] counted down from 255 (ML-DSA, d = a - b) or 127 (ML-KEM, d = b - a),
/// // then every coefficient by K[4] (in Montgomery form). lazy: the sums are not reduced (they stay below 2^32, and the
/// // difference is a + 2^l q - b in layer l).
/// INL void intt4(uint32_t *w, const uint32_t *zt, const uint32_t *K, const int kind, const int lazy) {
///   const C4 k = consts(K);
///   const V fv = S1(K[4]);
///   V c = k.q, o = OFF(c, &k);
///   unsigned m = kind == 0 ? 255 : 127;
///   if (kind == 0) {
///     for (unsigned j = 0; j < 256; j += 4) {
///       V x = LD(w + j), z = _mm_shuffle_epi32(_mm_loadl_epi64((const V *)(zt + m - 1)), 0x89); m -= 2;
///       V b = _mm_srli_epi64(x, 32), s = ADD(x, b), t = mont1(subo(x, b, o, &k), z, &k);
///       if (!lazy) { s = csub(s, &k); t = csub(t, &k); }
///       ST(w + j, _mm_or_si128(_mm_and_si128(s, k.lo), _mm_slli_epi64(t, 32)));
///     }
///     if (lazy) { c = ADD(c, c); o = OFF(c, &k); }
///   }
///   for (unsigned j = 0; j < 256; j += 8) {
///     V x = LD(w + j), y = LD(w + j + 4), a = _mm_unpacklo_epi64(x, y), b = _mm_unpackhi_epi64(x, y);
///     V z = _mm_shuffle_epi32(_mm_loadl_epi64((const V *)(zt + m - 1)), 0x89); m -= 2;
///     V s = ADD(a, b), t = mont(kind == 0 ? subo(a, b, o, &k) : subo(b, a, o, &k), z, &k);
///     if (!lazy) { s = csub(s, &k); t = csub(t, &k); }
///     ST(w + j, _mm_unpacklo_epi64(s, t)); ST(w + j + 4, _mm_unpackhi_epi64(s, t));
///   }
///   if (lazy) { c = ADD(c, c); o = OFF(c, &k); }
///   for (unsigned len = 4; len <= 128; len <<= 1) {
///     for (unsigned start = 0; start < 256; start += 2 * len) {
///       V z = S1(zt[m--]);
///       for (unsigned j = start; j < start + len; j += 4) {
///         V a = LD(w + j), b = LD(w + j + len);
///         V s = ADD(a, b), t = mont(kind == 0 ? subo(a, b, o, &k) : subo(b, a, o, &k), z, &k);
///         if (len == 128) { s = csub(mont(s, fv, &k), &k); t = csub(mont(t, fv, &k), &k); }
///         else if (!lazy) { s = csub(s, &k); t = csub(t, &k); }
///         ST(w + j, s); ST(w + j + len, t);
///       }
///     }
///     if (lazy) { c = ADD(c, c); o = OFF(c, &k); }
///   }
/// }
/// void F(dntt_l)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { ntt4(w, zt, K, 0, 1); }
/// void F(dntt_c)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { ntt4(w, zt, K, 0, 0); }
/// void F(dintt_l)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { intt4(w, zt, K, 0, 1); }
/// void F(dintt_c)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { intt4(w, zt, K, 0, 0); }
/// void F(kntt_l)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { ntt4(w, zt, K, 1, 1); }
/// void F(kntt_c)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { ntt4(w, zt, K, 1, 0); }
/// void F(kintt_l)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { intt4(w, zt, K, 1, 1); }
/// void F(kintt_c)(uint32_t *w, const uint32_t *zt, const uint32_t *K) { intt4(w, zt, K, 1, 0); }
/// // ML-DSA: out = a b (as the emitted code: a Montgomery product, then by R^2), and acc += a b
/// void F(dmul)(uint32_t *out, const uint32_t *a, const uint32_t *b, const uint32_t *K) {
///   const C4 k = consts(K); const V r2 = S1(K[6]);
///   for (unsigned j = 0; j < 256; j += 4) ST(out + j, csub(mont(mont2(LD(a + j), LD(b + j), &k), r2, &k), &k));
/// }
/// void F(dmuladd)(uint32_t *acc, const uint32_t *a, const uint32_t *b, const uint32_t *K) {
///   const C4 k = consts(K); const V r2 = S1(K[6]);
///   for (unsigned j = 0; j < 256; j += 4) {
///     V t = csub(mont(mont2(LD(a + j), LD(b + j), &k), r2, &k), &k);
///     ST(acc + j, csub(ADD(LD(acc + j), t), &k));
///   }
/// }
/// // ML-KEM: MultiplyNTTs with Barrett reductions (x - floor(x K[6] / 2^32) q, as x + floor(..) (2^32 - q))
/// INL V barrett(V x, V cb, const C4 *k) { return ADD(x, MUL(_mm_srli_epi64(MUL(x, cb), 32), k->negq)); }
/// void F(kmul)(uint32_t *out, const uint32_t *a, const uint32_t *b, const uint32_t *gam, const uint32_t *K) {
///   const C4 k = consts(K); const V cb = S1(K[6]);
///   for (unsigned j = 0; j < 256; j += 4) {
///     V x = LD(a + j), y = LD(b + j), xo = _mm_srli_epi64(x, 32), yo = _mm_srli_epi64(y, 32);
///     V p00 = MUL(x, y), p11 = MUL(xo, yo), cr = _mm_add_epi64(MUL(x, yo), MUL(xo, y));
///     V g = _mm_shuffle_epi32(_mm_loadl_epi64((const V *)(gam + j / 2)), 0x98);
///     V u = barrett(p11, cb, &k);
///     V c0 = barrett(_mm_add_epi64(MUL(u, g), p00), cb, &k), c1 = barrett(cr, cb, &k);
///     ST(out + j, csub(_mm_or_si128(_mm_and_si128(c0, k.lo), _mm_slli_epi64(c1, 32)), &k));
///   }
/// }
/// #ifndef MODEL
/// // ---- sixteen-bit lanes, signed Montgomery with R = 2^16. K: [0] q, [1] 20159, [2] 2 q, [3] 1/q mod 2^16, [4] q again
/// // (a second register, so that the compiler keeps the two subtractions apart), [5] 0xffffffff
/// #define W1(x) _mm_set1_epi16((short)(x))
/// INL V fqmul(V b, V z, V zq, V q) { V l = _mm_mullo_epi16(b, zq), h = _mm_mulhi_epi16(b, z); return _mm_sub_epi16(h, _mm_mulhi_epi16(l, q)); }
/// INL V fqmulv(V a, V b, V qi, V q) { V l = _mm_mullo_epi16(_mm_mullo_epi16(a, b), qi), h = _mm_mulhi_epi16(a, b); return _mm_sub_epi16(h, _mm_mulhi_epi16(l, q)); }
/// INL V cadd16(V d, V q) { return _mm_add_epi16(d, _mm_and_si128(_mm_srai_epi16(d, 15), q)); }
/// INL V csub16(V d, V q) { return cadd16(_mm_sub_epi16(d, q), q); }
/// INL V canon16(V x, V q, V v, V qb) { V t = _mm_srai_epi16(_mm_mulhi_epi16(x, v), 10); return csub16(_mm_sub_epi16(x, _mm_mullo_epi16(t, q)), qb); }
/// #define BFLY(a, b, z, zq) do { V t_ = fqmul(b, z, zq, q); if (lazy) { b = _mm_sub_epi16(a, t_); a = _mm_add_epi16(a, t_); } \
///   else { t_ = cadd16(t_, q); b = cadd16(_mm_sub_epi16(a, t_), q); a = csub16(_mm_add_epi16(a, t_), q); } } while (0)
/// // Z, ZQ: the zetas R mod q (centred) and those by 1/q, a register a block of butterflies (31), then two blocks (16),
/// // then four (16). w: 256 words of working space.
/// INL void nttw(uint32_t *f, int16_t *w, const V *Z, const V *ZQ, const uint32_t *K, const int lazy) {
///   const V q = W1(K[0]), v = W1(K[1]), qb = W1(K[4]), zero = _mm_setzero_si128();
///   unsigned i = 1;
///   for (unsigned j = 0; j < 128; j += 8) {
///     V a = _mm_packs_epi32(LD(f + j), LD(f + j + 4)), b = _mm_packs_epi32(LD(f + j + 128), LD(f + j + 132));
///     BFLY(a, b, Z[0], ZQ[0]); ST(w + j, a); ST(w + j + 128, b);
///   }
///   for (unsigned len = 64; len >= 8; len >>= 1)
///     for (unsigned start = 0; start < 256; start += 2 * len, i++)
///       for (unsigned j = start; j < start + len; j += 8) { V a = LD(w + j), b = LD(w + j + len); BFLY(a, b, Z[i], ZQ[i]); ST(w + j, a); ST(w + j + len, b); }
///   for (unsigned j = 0; j < 256; j += 16, i++) {
///     V x = LD(w + j), y = LD(w + j + 8), a = _mm_unpacklo_epi64(x, y), b = _mm_unpackhi_epi64(x, y);
///     BFLY(a, b, Z[i], ZQ[i]);
///     ST(w + j, _mm_unpacklo_epi64(a, b)); ST(w + j + 8, _mm_unpackhi_epi64(a, b));
///   }
///   for (unsigned j = 0; j < 256; j += 16, i++) {
///     V x = _mm_shuffle_epi32(LD(w + j), 0xd8), y = _mm_shuffle_epi32(LD(w + j + 8), 0xd8);
///     V a = _mm_unpacklo_epi64(x, y), b = _mm_unpackhi_epi64(x, y);
///     BFLY(a, b, Z[i], ZQ[i]);
///     if (lazy) { a = canon16(a, q, v, qb); b = canon16(b, q, v, qb); }
///     V l = _mm_unpacklo_epi32(a, b), h = _mm_unpackhi_epi32(a, b);
///     ST(f + j, _mm_unpacklo_epi16(l, zero)); ST(f + j + 4, _mm_unpackhi_epi16(l, zero));
///     ST(f + j + 8, _mm_unpacklo_epi16(h, zero)); ST(f + j + 12, _mm_unpackhi_epi16(h, zero));
///   }
/// }
/// void pq_w_ntt_l(uint32_t *f, int16_t *w, const V *Z, const V *ZQ, const uint32_t *K) { nttw(f, w, Z, ZQ, K, 1); }
/// void pq_w_ntt_c(uint32_t *f, int16_t *w, const V *Z, const V *ZQ, const uint32_t *K) { nttw(f, w, Z, ZQ, K, 0); }
/// // The inverse, every butterfly's results canonical: a' = a + b, b' = zeta (b - a); Z, ZQ: four blocks a register (16),
/// // two (16), then a block a register (8, 4, 2, 1), then 3303 R mod q.
/// #define IBFLY(a, b, z, zq) do { V d_ = _mm_sub_epi16(b, a); a = csub16(_mm_add_epi16(a, b), q); b = cadd16(fqmul(d_, z, zq, q), q); } while (0)
/// void pq_w_intt_c(uint32_t *f, int16_t *w, const V *Z, const V *ZQ, const uint32_t *K) {
///   const V q = W1(K[0]), zero = _mm_setzero_si128();
///   unsigned i = 0;
///   for (unsigned j = 0; j < 256; j += 16, i++) {
///     V x = _mm_shuffle_epi32(_mm_packs_epi32(LD(f + j), LD(f + j + 4)), 0xd8), y = _mm_shuffle_epi32(_mm_packs_epi32(LD(f + j + 8), LD(f + j + 12)), 0xd8);
///     V a = _mm_unpacklo_epi64(x, y), b = _mm_unpackhi_epi64(x, y);
///     IBFLY(a, b, Z[i], ZQ[i]);
///     ST(w + j, _mm_unpacklo_epi32(a, b)); ST(w + j + 8, _mm_unpackhi_epi32(a, b));
///   }
///   for (unsigned j = 0; j < 256; j += 16, i++) {
///     V x = LD(w + j), y = LD(w + j + 8), a = _mm_unpacklo_epi64(x, y), b = _mm_unpackhi_epi64(x, y);
///     IBFLY(a, b, Z[i], ZQ[i]);
///     ST(w + j, _mm_unpacklo_epi64(a, b)); ST(w + j + 8, _mm_unpackhi_epi64(a, b));
///   }
///   for (unsigned len = 8; len <= 64; len <<= 1)
///     for (unsigned start = 0; start < 256; start += 2 * len, i++)
///       for (unsigned j = start; j < start + len; j += 8) { V a = LD(w + j), b = LD(w + j + len); IBFLY(a, b, Z[i], ZQ[i]); ST(w + j, a); ST(w + j + len, b); }
///   for (unsigned j = 0; j < 128; j += 8) {
///     V a = LD(w + j), b = LD(w + j + 128), d = _mm_sub_epi16(b, a);
///     a = cadd16(fqmul(_mm_add_epi16(a, b), Z[i + 1], ZQ[i + 1], q), q);
///     b = cadd16(fqmul(fqmul(d, Z[i], ZQ[i], q), Z[i + 1], ZQ[i + 1], q), q);
///     ST(f + j, _mm_unpacklo_epi16(a, zero)); ST(f + j + 4, _mm_unpackhi_epi16(a, zero));
///     ST(f + j + 128, _mm_unpacklo_epi16(b, zero)); ST(f + j + 132, _mm_unpackhi_epi16(b, zero));
///   }
/// }
/// // MultiplyNTTs on four pairs a register. G, GQ: words (R^2, gamma R^2) mod q a pair, and those by 1/q (32 registers),
/// // then R^2 in every word.
/// void pq_w_mul(uint32_t *out, const uint32_t *a, const uint32_t *b, const V *G, const V *GQ, const uint32_t *K) {
///   const V q = W1(K[0]), q2 = W1(K[2]), qi = W1(K[3]), zero = _mm_setzero_si128();
///   const V lw = _mm_srli_epi32(S1(K[5]), 16), r2 = G[32], r2q = GQ[32];
///   for (unsigned j = 0, i = 0; j < 256; j += 8, i++) {
///     V A = _mm_packs_epi32(LD(a + j), LD(a + j + 4)), B = _mm_packs_epi32(LD(b + j), LD(b + j + 4));
///     V Bs = _mm_shufflehi_epi16(_mm_shufflelo_epi16(B, 0xb1), 0xb1);
///     V Y = fqmul(fqmulv(A, B, qi, q), G[i], GQ[i], q), Z = fqmul(fqmulv(A, Bs, qi, q), r2, r2q, q);
///     V s0 = _mm_add_epi16(Y, _mm_srli_epi32(Y, 16)), s1 = _mm_add_epi16(Z, _mm_srli_epi32(Z, 16));
///     V r = _mm_or_si128(_mm_and_si128(s0, lw), _mm_slli_epi32(s1, 16));
///     r = csub16(_mm_add_epi16(r, _mm_and_si128(_mm_srai_epi16(r, 15), q2)), q);
///     ST(out + j, _mm_unpacklo_epi16(r, zero)); ST(out + j + 4, _mm_unpackhi_epi16(r, zero));
///   }
/// }
/// #endif
/// ```
///
/// `desx.c`:
///
/// ```c
/// // desx.c: the 48 rounds of Triple DES on one block with pshufb look-ups (SSSE3), on a state already through IP with
/// // its halves rotated right by one, round keys as two words (the keys of S-boxes 0, 2, 4, 6 at bits 26, 18, 10, 2 of
/// // the first, of 1, 3, 5, 7 of the second): gcc's code of it is what module `xpq` times (`des3 pshufb-rounds`).
/// // T: 0x3f in eight bytes (16), the three index offsets (48), the 16 difference tables (256), the four masks (64).
/// #include <tmmintrin.h>
/// #include <stdint.h>
/// typedef __m128i V;
/// #define LDU(p) _mm_loadu_si128((const V *)(p))
/// static inline __attribute__((always_inline)) uint32_t rotl(uint32_t x, int r) { return (x << r) | (x >> (32 - r)); }
/// static inline __attribute__((always_inline)) uint32_t rotr(uint32_t x, int r) { return (x >> r) | (x << (32 - r)); }
/// static inline __attribute__((always_inline)) uint32_t fq(uint32_t Q, const uint32_t *k, const unsigned char *T) {
///   uint32_t u = Q ^ k[0], t = rotl(Q, 4) ^ k[1];
///   V x = _mm_unpacklo_epi32(_mm_cvtsi32_si128(u), _mm_cvtsi32_si128(t));
///   V v = _mm_and_si128(_mm_srli_epi32(x, 2), LDU(T));
///   V i1 = _mm_add_epi32(v, LDU(T + 16)), i2 = _mm_add_epi32(v, LDU(T + 32)), i3 = _mm_add_epi32(v, LDU(T + 48));
///   V acc = _mm_setzero_si128();
/// #define PAIR(p) { const unsigned char *D = T + 64 + 64 * (p); \
///     V a = _mm_xor_si128(_mm_shuffle_epi8(LDU(D + 48), v), _mm_shuffle_epi8(LDU(D), i1)); \
///     V b = _mm_xor_si128(_mm_shuffle_epi8(LDU(D + 16), i2), _mm_shuffle_epi8(LDU(D + 32), i3)); \
///     acc = _mm_xor_si128(acc, _mm_and_si128(_mm_xor_si128(a, b), LDU(T + 320 + 16 * (p)))); }
///   PAIR(0) PAIR(1) PAIR(2) PAIR(3)
///   acc = _mm_xor_si128(acc, _mm_srli_epi64(acc, 32));
///   uint32_t w = _mm_cvtsi128_si32(acc), o = 0;
///   o ^= rotr(w, 7) & 0x84448844u; o ^= rotr(w, 15) & 0x01002020u; o ^= rotr(w, 16) & 0x18094082u; o ^= rotr(w, 23) & 0x42820108u; o ^= rotr(w, 27) & 0x20100601u; o ^= rotr(w, 30) & 0x00201010u;
///   return o;
/// }
/// void pq_des_rounds(uint32_t *lr, const uint32_t *ks, const unsigned char *T) {
///   uint32_t l = lr[0], r = lr[1];
///   for (int pass = 0; pass < 3; pass++) {
/// #define R2(i) l ^= fq(r, ks + 4 * (i), T); r ^= fq(l, ks + 4 * (i) + 2, T);
///     R2(0) R2(1) R2(2) R2(3) R2(4) R2(5) R2(6) R2(7) ks += 32;
///     uint32_t t = l; l = r; r = t;
///   }
///   lr[0] = l; lr[1] = r;
/// }
/// ```
