    const KQ: u32 = 3329;
    const DQ: u32 = 8380417;

    #[repr(C, align(64))]
    #[derive(Clone, PartialEq)]
    struct Poly([u32; 256]);

    #[repr(C, align(64))]
    struct Regs<const N: usize>([[i16; 8]; N]);

    /// The candidates' tables (see `xpq.c`), from the tables the emitted
    /// functions write into their scratch areas.
    struct Tables {
        /// ML-KEM's zetas times 2^32 mod q, for the NTT and for its inverse.
        kzf: [u32; 128],
        kzi: [u32; 128],
        /// MultiplyNTTs' gammas.
        kg: [u32; 128],
        /// ML-DSA's zetas as the emitted NTT and its inverse hold them.
        tdf: [u32; 256],
        tdi: [u32; 256],
        kd: [u32; 8],
        kkf: [u32; 8],
        kki: [u32; 8],
        kw: [u32; 8],
        z: Regs<64>,
        zq: Regs<64>,
        zi: Regs<64>,
        zqi: Regs<64>,
        g: Regs<33>,
        gq: Regs<33>,
    }

    /// `-1/q mod 2^32`.
    fn ninv(q: u32) -> u32 {
        let mut x = 1u32;
        for _ in 0..6 {
            x = x.wrapping_mul(2u32.wrapping_sub(q.wrapping_mul(x)));
        }
        x.wrapping_neg()
    }

    /// `x 2^16 mod 3329`, centred.
    fn cm(x: u32) -> i16 {
        let z = (((x as u64) << 16) % KQ as u64) as i32;
        (if z > 1664 { z - 3329 } else { z }) as i16
    }

    fn setz<const N: usize>(z: &mut Regs<N>, zq: &mut Regs<N>, i: usize, v: [i16; 8]) {
        z.0[i] = v;
        zq.0[i] = v.map(|x| (x as i32).wrapping_mul(62209) as i16);
    }

    fn tables() -> Box<Tables> {
        let mut p = Poly([1; 256]);
        let mut s = Poly([0; 256]);
        let (mut tkf, mut tki, mut kg, mut tdf, mut tdi) = ([0u32; 128], [0u32; 128], [0u32; 128], [0u32; 256], [0u32; 256]);
        // SAFETY: cdecl; a polynomial and a scratch area of 1024 bytes each.
        unsafe {
            vgx_pq_e_mlkem_ntt(p.0.as_mut_ptr(), s.0.as_mut_ptr());
            tkf.copy_from_slice(&s.0[..128]);
            p = Poly([1; 256]);
            vgx_pq_e_mlkem_inv_ntt(p.0.as_mut_ptr(), s.0.as_mut_ptr());
            tki.copy_from_slice(&s.0[..128]);
            let (a, b) = (Poly([1; 256]), Poly([2; 256]));
            vgx_pq_e_mlkem_multiply_ntts(p.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), s.0.as_mut_ptr());
            kg.copy_from_slice(&s.0[..128]);
            p = Poly([1; 256]);
            vgx_pq_e_mldsa_ntt(p.0.as_mut_ptr(), s.0.as_mut_ptr());
            tdf.copy_from_slice(&s.0);
            p = Poly([1; 256]);
            vgx_pq_e_mldsa_inv_ntt(p.0.as_mut_ptr(), s.0.as_mut_ptr());
            tdi.copy_from_slice(&s.0);
        }
        let r = |x: u32| (((x as u64) << 32) % KQ as u64) as u32;
        let mut t = Box::new(Tables {
            kzf: tkf.map(r),
            kzi: tki.map(r),
            kg,
            tdf,
            tdi,
            kd: [DQ, ninv(DQ), !0, 1, 16382, DQ.wrapping_neg(), 2365951, (1 << 23) - 1],
            kkf: [KQ, ninv(KQ), !0, 1, r(1), KQ.wrapping_neg(), 1290167, 0],
            kki: [KQ, ninv(KQ), !0, 1, r(3303), KQ.wrapping_neg(), 1290167, 0],
            kw: [3329, 20159, 6658, 62209, 3329, !0, 0, 0],
            z: Regs([[0; 8]; 64]),
            zq: Regs([[0; 8]; 64]),
            zi: Regs([[0; 8]; 64]),
            zqi: Regs([[0; 8]; 64]),
            g: Regs([[0; 8]; 33]),
            gq: Regs([[0; 8]; 33]),
        });
        let mut i = 0;
        for k in 1..32 {
            setz(&mut t.z, &mut t.zq, i, [cm(tkf[k]); 8]);
            i += 1;
        }
        for k in (32..64).step_by(2) {
            setz(&mut t.z, &mut t.zq, i, core::array::from_fn(|j| cm(tkf[k + j / 4])));
            i += 1;
        }
        for k in (64..128).step_by(4) {
            setz(&mut t.z, &mut t.zq, i, core::array::from_fn(|j| cm(tkf[k + j / 2])));
            i += 1;
        }
        assert_eq!(i, 63);
        i = 0;
        for b in (0..64).step_by(4) {
            setz(&mut t.zi, &mut t.zqi, i, core::array::from_fn(|j| cm(tki[127 - b - j / 2])));
            i += 1;
        }
        for b in (0..32).step_by(2) {
            setz(&mut t.zi, &mut t.zqi, i, core::array::from_fn(|j| cm(tki[63 - b - j / 4])));
            i += 1;
        }
        for top in [31usize, 15, 7, 3, 1] {
            for b in 0..=top / 2 {
                setz(&mut t.zi, &mut t.zqi, i, [cm(tki[top - b]); 8]);
                i += 1;
            }
        }
        setz(&mut t.zi, &mut t.zqi, i, [cm(3303); 8]);
        assert_eq!(i, 63);
        for p in 0..32 {
            let v = core::array::from_fn(|j| if j & 1 == 1 { cm((((kg[4 * p + j / 2] as u64) << 16) % KQ as u64) as u32) } else { cm(1 << 16) });
            setz(&mut t.g, &mut t.gq, p, v);
        }
        setz(&mut t.g, &mut t.gq, 32, [cm(1 << 16); 8]);
        t
    }

    /// `x` is the polynomial worked on (the result, or the sum added to),
    /// `a` and `b` the operands of a multiplication.
    type Op<'a> = Box<dyn Fn(&mut Poly, &Poly, &Poly) + 'a>;

    struct Group<'a> {
        op: &'static str,
        q: u32,
        unary: bool,
        emitted: Op<'a>,
        cands: Vec<(&'static str, Op<'a>)>,
    }

    /// The functions timed: the emitted one of each operation and its candidates (each with its MCDT frame).
    fn groups<'a>(t: &'a Tables, s: *mut u32, w: *mut i16) -> Vec<Group<'a>> {
        // SAFETY (every call below): cdecl; polynomials of 256 words, the tables of `Tables`, a scratch area of 1024
        // bytes and 256 words of working space; SSE2 is in the baseline of the target.
        vec![
            Group {
                op: "kem-ntt",
                q: KQ,
                unary: true,
                emitted: Box::new(move |x, _, _| unsafe { vgx_pq_e_mlkem_ntt(x.0.as_mut_ptr(), s) }),
                cands: vec![
                    ("p.lazy.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_kntt_l(x.0.as_mut_ptr(), t.kzf.as_ptr(), t.kkf.as_ptr()) })),
                    ("p.lazy.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_kntt_l(x.0.as_mut_ptr(), t.kzf.as_ptr(), t.kkf.as_ptr()) })),
                    ("p.canon.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_kntt_c(x.0.as_mut_ptr(), t.kzf.as_ptr(), t.kkf.as_ptr()) })),
                    ("p.canon.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_kntt_c(x.0.as_mut_ptr(), t.kzf.as_ptr(), t.kkf.as_ptr()) })),
                    ("w.lazy", Box::new(move |x, _, _| unsafe { vgx_pq_w_ntt_l(x.0.as_mut_ptr(), w, t.z.0.as_ptr(), t.zq.0.as_ptr(), t.kw.as_ptr()) })),
                    ("w.canon", Box::new(move |x, _, _| unsafe { vgx_pq_w_ntt_c(x.0.as_mut_ptr(), w, t.z.0.as_ptr(), t.zq.0.as_ptr(), t.kw.as_ptr()) })),
                ],
            },
            Group {
                op: "kem-intt",
                q: KQ,
                unary: true,
                emitted: Box::new(move |x, _, _| unsafe { vgx_pq_e_mlkem_inv_ntt(x.0.as_mut_ptr(), s) }),
                cands: vec![
                    ("p.lazy.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_kintt_l(x.0.as_mut_ptr(), t.kzi.as_ptr(), t.kki.as_ptr()) })),
                    ("p.lazy.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_kintt_l(x.0.as_mut_ptr(), t.kzi.as_ptr(), t.kki.as_ptr()) })),
                    ("p.canon.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_kintt_c(x.0.as_mut_ptr(), t.kzi.as_ptr(), t.kki.as_ptr()) })),
                    ("p.canon.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_kintt_c(x.0.as_mut_ptr(), t.kzi.as_ptr(), t.kki.as_ptr()) })),
                    ("w.canon", Box::new(move |x, _, _| unsafe { vgx_pq_w_intt_c(x.0.as_mut_ptr(), w, t.zi.0.as_ptr(), t.zqi.0.as_ptr(), t.kw.as_ptr()) })),
                ],
            },
            Group {
                op: "kem-mul",
                q: KQ,
                unary: false,
                emitted: Box::new(move |x, a, b| unsafe { vgx_pq_e_mlkem_multiply_ntts(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), s) }),
                cands: vec![
                    ("p.m", Box::new(move |x, a, b| unsafe { vgx_pq_m_kmul(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.kg.as_ptr(), t.kkf.as_ptr()) })),
                    ("p.s", Box::new(move |x, a, b| unsafe { vgx_pq_s_kmul(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.kg.as_ptr(), t.kkf.as_ptr()) })),
                    ("w", Box::new(move |x, a, b| unsafe { vgx_pq_w_mul(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.g.0.as_ptr(), t.gq.0.as_ptr(), t.kw.as_ptr()) })),
                ],
            },
            Group {
                op: "dsa-ntt",
                q: DQ,
                unary: true,
                emitted: Box::new(move |x, _, _| unsafe { vgx_pq_e_mldsa_ntt(x.0.as_mut_ptr(), s) }),
                cands: vec![
                    ("p.lazy.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_dntt_l(x.0.as_mut_ptr(), t.tdf.as_ptr(), t.kd.as_ptr()) })),
                    ("p.lazy.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_dntt_l(x.0.as_mut_ptr(), t.tdf.as_ptr(), t.kd.as_ptr()) })),
                    ("p.canon.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_dntt_c(x.0.as_mut_ptr(), t.tdf.as_ptr(), t.kd.as_ptr()) })),
                    ("p.canon.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_dntt_c(x.0.as_mut_ptr(), t.tdf.as_ptr(), t.kd.as_ptr()) })),
                ],
            },
            Group {
                op: "dsa-intt",
                q: DQ,
                unary: true,
                emitted: Box::new(move |x, _, _| unsafe { vgx_pq_e_mldsa_inv_ntt(x.0.as_mut_ptr(), s) }),
                cands: vec![
                    ("p.lazy.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_dintt_l(x.0.as_mut_ptr(), t.tdi.as_ptr(), t.kd.as_ptr()) })),
                    ("p.lazy.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_dintt_l(x.0.as_mut_ptr(), t.tdi.as_ptr(), t.kd.as_ptr()) })),
                    ("p.canon.m", Box::new(move |x, _, _| unsafe { vgx_pq_m_dintt_c(x.0.as_mut_ptr(), t.tdi.as_ptr(), t.kd.as_ptr()) })),
                    ("p.canon.s", Box::new(move |x, _, _| unsafe { vgx_pq_s_dintt_c(x.0.as_mut_ptr(), t.tdi.as_ptr(), t.kd.as_ptr()) })),
                ],
            },
            Group {
                op: "dsa-mul",
                q: DQ,
                unary: false,
                emitted: Box::new(move |x, a, b| unsafe { vgx_pq_e_mldsa_multiply_ntt(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr()) }),
                cands: vec![
                    ("p.m", Box::new(move |x, a, b| unsafe { vgx_pq_m_dmul(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.kd.as_ptr()) })),
                    ("p.s", Box::new(move |x, a, b| unsafe { vgx_pq_s_dmul(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.kd.as_ptr()) })),
                ],
            },
            Group {
                op: "dsa-muladd",
                q: DQ,
                unary: false,
                emitted: Box::new(move |x, a, b| unsafe { vgx_pq_e_mldsa_multiply_add_ntt(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr()) }),
                cands: vec![
                    ("p.m", Box::new(move |x, a, b| unsafe { vgx_pq_m_dmuladd(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.kd.as_ptr()) })),
                    ("p.s", Box::new(move |x, a, b| unsafe { vgx_pq_s_dmuladd(x.0.as_mut_ptr(), a.0.as_ptr(), b.0.as_ptr(), t.kd.as_ptr()) })),
                ],
            },
        ]
    }

